import { cookies } from 'next/headers';

export interface UserPreferences {
  theme: 'light' | 'dark' | 'system';
  language: string;
  notifications: boolean;
  updatedAt: string;
}

export async function GET(): Promise<Response> {
  // Simulate user-specific data that changes per request
  // In a real app, you'd read from session/cookies/database
  const cookieStore = await cookies();
  const themeCookie = cookieStore.get('theme')?.value;
  const langCookie = cookieStore.get('language')?.value;

  const preferences: UserPreferences = {
    theme: (themeCookie as UserPreferences['theme']) || 'system',
    language: langCookie || 'en',
    notifications: true,
    updatedAt: new Date().toISOString(),
  };

  return Response.json(preferences);
}

