import { headers } from 'next/headers';

interface UserPreferences {
  theme: 'light' | 'dark' | 'system';
  language: string;
  notifications: boolean;
  updatedAt: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  const headersList = await headers();
  const host = headersList.get('host') || 'localhost:3000';
  const protocol = headersList.get('x-forwarded-proto') || 'http';
  const baseUrl = `${protocol}://${host}`;

  const res = await fetch(`${baseUrl}/api/user/preferences`, {
    cache: 'no-store',
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div>
        <h3>Your Preferences</h3>
        <ul>
          <li>
            <strong>Theme:</strong> {preferences.theme}
          </li>
          <li>
            <strong>Language:</strong> {preferences.language}
          </li>
          <li>
            <strong>Notifications:</strong>{' '}
            {preferences.notifications ? 'Enabled' : 'Disabled'}
          </li>
          <li>
            <strong>Last updated:</strong> {preferences.updatedAt}
          </li>
        </ul>
      </div>
    </div>
  );
}

